from typing import Tuple
import numpy as np
from scipy.optimize import minimize

def cubic_function(x: float) -> float:
    """Cubic function y = f(x)"""
    return 0.1 * x**3 - 0.5 * x**2 + x + 1

def road_function(x: float) -> float:
    """Road function g(x) = (x + 1)/(x - 2) for x > 2"""
    return (x + 1) / (x - 2)

def distance_to_road(point: Tuple[float, float], x: float) -> float:
    """Calculate the distance between a point (mx, my) and the curve g(x)"""
    y = road_function(x)
    return np.sqrt((x - point[0])**2 + (y - point[1])**2)

def solve_min_distance(mx: float, my: float) -> float:
    """
    Calculate the minimum distance between a point (mx, my) and the curve g(x)
    then multiply by 10 to convert to meters and round to two decimal places.

    Parameters:
    mx (float): x-coordinate of the point
    my (float): y-coordinate of the point

    Returns:
    float: Minimum distance in meters
    """
    def objective(x: float) -> float:
        return distance_to_road((mx, my), x)

    res = minimize(objective, 3, method="SLSQP", bounds=[(2, 100)])
    return round(res.fun * 10, 2)
