import math

def calculate_p_scaled(n, k, scale):
    def calculate_p(n, k):
        if k > n:
            return 0
        if k < 0:
            return 0
        if k == 0 or k == n:
            return 1
        numerator = math.comb(n, k)
        denominator = sum(math.comb(n, i) * math.comb(n-i, k-i) for i in range(k+1))
        return numerator / denominator

    def is_valid_configuration(configuration):
        for i in range(n):
            if configuration[i] > 2:
                return False
        ones = sum(1 for i in range(n) if configuration[i] == 1)
        twos = sum(1 for i in range(n) if configuration[i] == 2)
        if ones not in [4, 6] or twos > 0:
            return False
        for i in range(n):
            if configuration[i] == 2 and (i == 0 or configuration[i-1] != 0) and (i == n-1 or configuration[i+1] != 0):
                return False
        return True

    p = 0
    for configuration in generate_configurations(n, k):
        if is_valid_configuration(configuration):
            p += 1
    return scale * p

def generate_configurations(n, k):
    if k == 0:
        yield [0] * n
    else:
        for i in range(n):
            for configuration in generate_configurations(i, k-1):
                yield [0] * i + [2] + configuration + [0] * (n - i - 1)

